const input = Array.isArray($json) ? $json : [$json];
return input.map((visit) => {
  const status = `${visit.frontDeskStatus ?? ''}`.toLowerCase();
  const eligible = visit.reviewEligible === true && status.includes('happy');
  return { json: { ...visit, reviewAction: eligible ? 'send-review-request' : 'office-manager-follow-up-first' } };
});
